[{"order":1,"type":"heading","text":"UI Testing with Jetpack Compose Testing Library"},{"order":2,"type":"paragraph","text":"Jetpack Compose provides a robust and intuitive testing library that allows developers to verify the behavior of their composable functions. This tutorial explores how to write effective UI tests for Android applications built with Jetpack Compose using Kotlin."},{"order":3,"type":"subheading","text":"Prerequisites and Dependencies"},{"order":4,"type":"paragraph","text":"To get started with Compose testing, you need to include the necessary testing artifacts in your module level build.gradle.kts file. These dependencies provide the ComposeTestRule and idling registry mechanisms."},{"order":5,"type":"code","text":"androidTestImplementation("androidx.compose.ui:ui-test-junit4:1.6.0")
debugImplementation("androidx.compose.ui:ui-test-manifest:1.6.0")"},{"order":6,"type":"subheading","text":"Setting Up Your First Compose Test"},{"order":7,"type":"paragraph","text":"Compose UI tests are typically instrumented tests located in the androidTest directory. You use the createComposeRule() extension to set the content you want to test and interact with it."},{"order":8,"type":"code","text":"import androidx.compose.material3.Text
import androidx.compose.ui.test.junit4.createComposeRule
import androidx.compose.ui.test.onNodeWithText
import androidx.compose.ui.test.assertIsDisplayed
import org.junit.Rule
import org.junit.Test

class HelloWorldTest {
    @get:Rule
    val composeTestRule = createComposeRule()

    @Test
    function myTest() {
        composeTestRule.setContent {
            Text("Hello Compose")
        }

        composeTestRule.onNodeWithText("Hello Compose").assertIsDisplayed()
    }
}"},{"order":9,"type":"subheading","text":"Key Concepts in Compose Testing"},{"order":10,"type":"bullet_point","text":"ComposeTestRule: The entry point for testing Compose code. It manages the lifecycle of the composable and synchronization."},{"order":11,"type":"bullet_point","text":"Semantics: Compose uses a semantics tree parallel to the composition tree to describe UI elements for testing and accessibility."},{"order":12,"type":"bullet_point","text":"Finders: Methods like onNodeWithText, onNodeWithTag, and onNodeWithContentDescription used to locate specific nodes."},{"order":13,"type":"bullet_point","text":"Actions: Methods like performClick, performTextInput, and performScrollTo applied on nodes."},{"order":14,"type":"bullet_point","text":"Assertions: Methods like assertIsDisplayed, assertTextEquals, and assertIsEnabled used to verify node states."},{"order":15,"type":"subheading","text":"Testing User Interaction and State Changes"},{"order":16,"type":"paragraph","text":"Testing interactive elements requires triggering actions and asserting that the state updates accordingly. Consider a simple counter component that increments when a button is clicked."},{"order":17,"type":"code","text":"import androidx.compose.foundation.layout.Column
import androidx.compose.material3.Button
import androidx.compose.material3.Text
import androidx.compose.runtime.*
import androidx.compose.ui.Modifier
import androidx.compose.ui.platform.testTag

@Composable
function CounterComponent() {
    var count by remember { mutableStateOf(0) }
    Column {
        Button(
            onClick = { count++ },
            modifier = Modifier.testTag("incrementButton")
        ) {
            Text("Increment")
        }
        Text("Count: $count", modifier = Modifier.testTag("countText"))
    }
}"},{"order":18,"type":"paragraph","text":"Here is how you would write an instrumented test for the CounterComponent using test tags to uniquely identify the nodes."},{"order":19,"type":"code","text":"import androidx.compose.ui.test.junit4.createComposeRule
import androidx.compose.ui.test.onNodeWithTag
import androidx.compose.ui.test.performClick
import androidx.compose.ui.test.assertTextEquals
import org.junit.Rule
import org.junit.Test

class CounterTest {
    @get:Rule
    val composeTestRule = createComposeRule()

    @Test
    function testCounterIncrements() {
        composeTestRule.setContent {
            CounterComponent()
        }

        composeTestRule.onNodeWithTag("countText").assertTextEquals("Count: 0")

        composeTestRule.onNodeWithTag("incrementButton").performClick()

        composeTestRule.onNodeWithTag("countText").assertTextEquals("Count: 1")
    }
}"},{"order":20,"type":"subheading","text":"Best Practices"},{"order":21,"type":"bullet_point","text":"Prefer semantic finders like onNodeWithText or onNodeWithContentDescription over test tags for better accessibility alignment."},{"order":22,"type":"bullet_point","text":"Use Modifier.testTag only when standard semantic properties are insufficient."},{"order":23,"type":"bullet_point","text":"Keep your tests isolated by testing individual composables or small feature screens independently."}]
